\label{thm:sge}
Let $\{x_t\}$ be generated by Algorithm~\ref{alg:sge}. 
Set $\alpha_t=\frac{t-1}{t}$, $\tau_t=\frac{t-1}{3}$, $\eta_t=\frac{\eta}{t}$ for $t\le2$, and $\eta_t=\frac{\eta}{t}+\frac{\mu(t-3)}{2}$ for $t\ge3$, where
$\eta\ge\max\{24L,\frac{54\ensuremath{\mathcal{L}}}{m} + \frac{162\ensuremath{\mathcal{L}}^2}{\mu m^2}\}$. Then\footnote{The second inequality in \eqref{eq:sge-rate} is proved using $\nabla f(x^*) = 0$, and the first inequality is proved without this assumption.}, for $k\ge3$,
\begin{align}
\mathbb{E}[f(x_k)-f^*]
\le &\left(
\tfrac{72L}{k(k+2)}
+\tfrac{162\ensuremath{\mathcal{L}}}{mk(k+2)}
+\tfrac{486\ensuremath{\mathcal{L}}^2}{\mu m^2k(k+2)}
\right)\|x_0-x^*\|^2 + \tfrac{2}{9k(k+2)}[f(x_0)-f^*]+\tfrac{192\sigma_*^2}{\mu m(k+2)}
+\tfrac{216\mathcal{B}^2}{\mu}\nonumber\\
\le&
\left(
\tfrac{73L}{k(k+2)}
+\tfrac{162\ensuremath{\mathcal{L}}}{mk(k+2)}
+\tfrac{486\ensuremath{\mathcal{L}}^2}{\mu m^2k(k+2)}
\right)\|x_0-x^*\|^2 +\tfrac{192\sigma_*^2}{\mu m(k+2)}
+\tfrac{216\mathcal{B}^2}{\mu}. \label{eq:sge-rate}
\end{align}
In particular,  for $m = 1$ and $k \geq \max \{98\sqrt{\tfrac{L}{\mu}}, 144\sqrt{\tfrac{\ensuremath{\mathcal{L}}}{\mu}}, \tfrac{102\ensuremath{\mathcal{L}}}{\mu}, \tfrac{3072\sigma_*^2}{\mu^2\|x_0-x^*\|^2}\}$, we have
\begin{align}\label{sge_contraction}
\mathbb{E}\|x_k - x^*\|^2 \leq \tfrac{2}{\mu}\mathbb{E}[f(x_k)-f^*] \leq \tfrac{1}{4}\|x_0-x^*\|^2 + \tfrac{432 \mathcal{B}^2}{\mu^2}.
\end{align}

\label{corollary_known}
Suppose all oracles are unbiased, i.e., $B_\lambda = 0,~\forall \lambda$. Define $A_\lambda=c_\lambda \max \left\{98\sqrt{\frac{L}{\mu}}, 144\sqrt{\tfrac{\ensuremath{\mathcal{L}}_\lambda}{\mu}}, \tfrac{102\ensuremath{\mathcal{L}}_\lambda}{\mu}\right\}$ and $B_\lambda=c_\lambda \cdot \frac{3072\sigma^2_{\lambda,*}}{\mu^2R_0^2}$. For $\epsilon >0$, let $K=\lceil\log_2(R_0^2/\epsilon)\rceil$. Then the total costs of  Algorithm \ref{alg:known} and using the best-fixed oracle throughout satisfy
\begin{align}\label{total_cost_results}
\mathrm{Cost}_{\rm adap}(\epsilon)&=\sum_{s=1}^K\min_\lambda\max\{A_\lambda,B_\lambda2^{s-1}\}, \nonumber\\
\mathrm{Cost}_{\rm fixed}(\epsilon)&=\min_\lambda\sum_{s=1}^K\max\{A_\lambda,B_\lambda2^{s-1}\} = \mathcal{O}\left( \min_{\lambda} \left\{c_\lambda \cdot \left(\sqrt{\tfrac{L}{\mu}}\log_2\tfrac{R_0^2}{\epsilon} +\tfrac{\ensuremath{\mathcal{L}}_\lambda}{\mu}\log_2\tfrac{R_0^2}{\epsilon} + \tfrac{\sigma_{\lambda,*}^2}{\mu^2 \epsilon}\right)\right\}  \right),
\end{align}
hence $\mathrm{Cost}_{\rm adap}(\epsilon)\le\mathrm{Cost}_{\rm fixed}(\epsilon)$. 
Moreover, there exist instances for which $ \frac{\mathrm{Cost}_{\rm fixed}(\epsilon)}
     {\mathrm{Cost}_{\rm adap}(\epsilon)}= \Theta\!\left(\tfrac{K}{\log K}\right) = \Theta\!\left(
\tfrac{\log(R_0^2/\epsilon)}
{\log\log(R_0^2/\epsilon)}
\right) $, and this order is tight for stage costs of the form
$\max\{A_\lambda,B_\lambda2^{s-1}\}$.

\label{lem:pg-certificate}
Let $X$ be closed and convex and suppose $x^*\in X$.
For any $\gamma\le2/L$, we have
\begin{align}\label{decent_ineq}
    f(x) - f(x^+) \geq (\gamma - \tfrac{\gamma^2L}{2})
\|\mathsf{G}_{X,\gamma}(x)\|^2,
\end{align}
and
\begin{align}\label{projected_gradient_ineq}
    \|x-x^*\|
    \le
    \tfrac{2}{\mu}
    \|\mathsf{G}_{X,\gamma}(x)\|.
\end{align}
Consequently, $\|\mathsf{G}_{X,\gamma}(x)\|
    \le
    \tfrac{\sqrt{2}\mu R}{4}$ implies $\|x-x^*\|^2\le\tfrac{R^2}{2}$.

\label{lem:block-validity}
Suppose $y^s$ is certified at level $s$, and let $\lambda$ be block-admissible for a planned block $(s,t)$. Then the output point
$
z=\mathsf{Block}(y^s;s,t,\lambda)
$
satisfies
\begin{equation}
\mathbb{E}\|\mathsf{G}_X(z)\|
\le
\tfrac{\sqrt{2}\mu R_{t-1}}{16},
\label{eq:block-expected-pg}
\end{equation}
and consequently
\begin{equation}
\ensuremath{{\mathbb{P}}}\left(
\|\mathsf{G}_X(z)\|
\le
\tfrac{\sqrt{2}\mu R_{t-1}}{4}
\right)
\ge \tfrac34.
\label{eq:block-success}
\end{equation}

\label{prop:sequential-block-cert}
Suppose a planned block is block-admissible, and let $N$ be the number of trials used by the sequential rule in Algorithm~\ref{alg:budgeted-certification}, truncated after $\mathcal R$ trials. Then
\begin{equation}\label{eq:sequential-expected-trials}
\ensuremath{{\mathbb{P}}}(\text{the block certification fails})
\le4^{-\mathcal R}, \quad \text{and}\quad \mathbb{E}[N]\le\tfrac43.
\end{equation}

\label{thm:rr-sge-subroutine}

Set $
    S=1+\left\lceil\log_2\frac{L}{\mu}\right\rceil.
$ Suppose the initial point $\widehat x_0$ satisfies
$
    \mathbb{E}\|\widehat x_0-x^*\|^2\le R^2.
$
There exists a universal constant $c_0>0$ such that, if
\begin{equation}
    \mathcal{B}
    \le
    \tfrac{c_0\mu R}{S},
    \label{eq:cert-bias-condition}
\end{equation}
then Algorithm~\ref{alg:rr-sge} returns a point $\widehat y\in X$ satisfying
\begin{equation}
    \mathbb{E}\|\mathsf{G}_{X}(\widehat y)\|
    \le
    \tfrac{\sqrt{2}\mu R}{16}, ~~\text{and hence}~~\ensuremath{{\mathbb{P}}}\!\left(
       \|\mathsf{G}_{X}(\widehat y)\|
       \le \tfrac{\sqrt{2}\mu R}{4}
    \right)
    \ge\tfrac34.
    \label{eq:cert-constant-prob}

\end{equation}









The total number of stochastic-gradient evaluations is at most
\begin{equation}
\mathcal{O}\left(
S\left(
    \sqrt{\tfrac{L}{\mu}}
    +
    \tfrac{\ensuremath{\mathcal{L}}}{\mu}

\right)
+
\tfrac{S^3\sigma_*^2}{\mu^2R^2}
\right).
\label{eq:cert-candidate-complexity}
\end{equation}
Consequently, Algorithm~\ref{alg:rr-sge} is a valid projected-gradient reduction subroutine
$
\mathsf{PGReduce}^{\rm RR+SGE}(y,R;\mathrm{SO}_\lambda)
$
with $\mathcal{B}_\lambda\le
\tfrac{c_0\mu R}{1+\lceil\log_2(L/\mu)\rceil}$ as the bias-admissibility condition $\mathsf{Adm}_{\rm PG}^{\rm RR+SGE}(R,\mathcal{B}_\lambda)$






and
\[
\widetilde T^{\rm RR+SGE}(R,\lambda)
=
\widetilde O\!\left(T^{\rm SGE}(R,\lambda)\right).
\]

\label{thm:budgeted-cost}
Consider Algorithm~\ref{alg:budgeted-certification} on the high-probability event in Proposition~\ref{prop:budgeted-correctness}. For $B>0$, let
$
\bar B:=\min\{B,C_{\rm sw}^{\rm PG}\}.
$
We have
\begin{align}
\mathrm{Cost}_B
\le\;&
\mathcal R
\left[
\zeta C_{\rm sw}^{\rm PG}
+
C_{\rm bad}^{\rm PG}
+
M\bar B
\right]
\nonumber\\
&+
\mathcal R c_{\rm cert}
\left[
\min\left\{
K,\,
\left\lceil\frac{C_{\rm sw}^{\rm PG}}{B}\right\rceil+Q+1
\right\}
+M
\right].
\label{eq:budgeted-cost-first}






















\end{align}

\label{cor:budgeted-U}
For $0<B\le C_{\rm sw}^{\rm PG}$, define
\begin{equation}
C_{\rm B-independent}
:=
\mathcal R
\left[
\zeta C_{\rm sw}^{\rm PG}
+
C_{\rm bad}^{\rm PG}
\right]
+
\mathcal R c_{\rm cert}
\left[
\binom{\ell}{2}+\ell+2
\right].
\label{eq:budgeted-fixed-cost}
\end{equation}
Then we have
\begin{equation}
\mathrm{Cost}_B
\le
C_{\rm B-independent}
+
\mathcal R
\left[
\ell B
+
\tfrac{c_{\rm cert}C_{\rm sw}^{\rm PG}}{B}
\right].
\label{eq:budgeted-clean-U}
\end{equation}
The $B$-dependent upper bound is minimized at
$
B^\star
=
\sqrt{
\tfrac{c_{\rm cert}C_{\rm sw}^{\rm PG}}{\ell}
}$,
whenever $B^\star\le C_{\rm sw}^{\rm PG}$, with 
$
\mathrm{Cost}_{B^*}
\le
C_{\rm B-independent}
+2\mathcal R
\sqrt{
\ell c_{\rm cert}C_{\rm sw}^{\rm PG}
}$.

\label{prop:general_convergence}
Suppose $\{z_t\}$ and $\{x_t\}$ are generated by Algorithm~\ref{alg:sge}. Let the algorithm parameters $\{\alpha_t\}$, $\{\eta_t\}$ and $\{\tau_t\}$ satisfy $\tau_1 \geq 0,$ $\tau_t > 0$ for all $t\geq 2$, along with relations
\begin{subequations}
\label{eq:def_rell}
\begin{align}
\theta_{t-1} &= \alpha_t \theta_t, ~~\eta_t \le \alpha_t (\eta_{t-1} + \mu\alpha_{t-1}) , ~~ t= 2, \ldots,k \label{eq:def_eta_rel}\\


\tfrac{\eta_t \tau_{t-1}}{\alpha_{t}} &\ge{4}L,

\quad t= 3, \ldots, k \label{eq:def_Lip_rel}\\
 \tfrac{\eta_1\eta_2}{\alpha_2} &\geq  {16}L^2, ~~\eta_k \tau_k  \ge 2L, \label{eq:def_Lip_rel1}
\end{align}
\end{subequations}
 for some $\theta_t \ge 0$.
Then for all $x \in X$
\begin{align}
&\sum_{t=1}^k \theta_t \left\{  \tau_t [f(x_t) -f(x_{t-1})]- [\langle \nabla f(x_t), x - x_t \rangle + \tfrac{\mu}{2}\|x_t-x\|^2]\right\} + \tfrac{\theta_k}{2}(\tfrac{\eta_k}{2} + \mu\alpha_k ) \|z_k-x\|^2 \nonumber\\
&\leq \tfrac{\theta_1\eta_1}{2}\|x_0-x\|^2 - \tfrac{\theta_k \mu}{2}\|x_k-x\|^2- \sum_{t=1}^k \theta_t \langle {b(x_{t-1}) + \alpha_t (b(x_{t-1}) - b(x_{t-2}))}, z_t - x\rangle\nonumber\\
&\quad + \sum_{t=0}^{k-1}\left[  \tfrac{2\theta_{t+1}(1+\alpha_{t+1}^2)}{\eta_{t+1}}\|\delta_t(x_t)\|^2 + \tfrac{2\theta_{t+2}\alpha_{t+2}^2}{\eta_{t+2}}\|\delta_{t+1}(x_t)\|^2 \right]\nonumber\\
&\quad + {\sum_{t=0}^{k-1}  \theta_{t+1} \langle\alpha_{t+1} \delta_{t}(x_{t-1})- (1+\alpha_{t+1})\delta_{t}(x_{t}), z_{t} - x\rangle}.
\label{eq:prop_GEM_main_general}
\end{align}
where $g(x) := \mathbb{E}[G_t(x)]$, $b(x) := g(x)-\nabla f(x)$, and 



$\delta_t(x):=G_t(x)-g(x)$.
